import { TOPOLOGY_PAGE_PROFILES } from "../config/topologyPageProfiles";
import { createHexGrid, getGridBounds } from "./hex";
import {
  OPERATIONAL_DASHBOARD_EDGES,
  OPERATIONAL_DASHBOARD_NODES,
  OPERATIONAL_DASHBOARD_RECORDS,
  OPERATIONAL_DASHBOARD_RECORDS_BY_ID,
  OPERATIONAL_DASHBOARD_SELECTOR_GROUPS,
} from "./operationalDashboardData";

export function createOperationalDashboardSceneTopology() {
  const dashboardProfile = TOPOLOGY_PAGE_PROFILES.operationalDashboard;
  const dashboardRadius = dashboardProfile.scene.radius;
  const dashboardCells = createHexGrid({
    radius: dashboardRadius,
    columns: dashboardProfile.scene.columns,
    rows: dashboardProfile.scene.rows,
    originQ: dashboardProfile.scene.originQ,
    originR: dashboardProfile.scene.originR,
  });
  const dashboardBounds = getGridBounds(dashboardCells, dashboardRadius);
  const selectedId = "internet-facing-service";
  const selectedRecord =
    OPERATIONAL_DASHBOARD_RECORDS_BY_ID[selectedId] ?? OPERATIONAL_DASHBOARD_RECORDS[0];
  const dashboardJson = JSON.stringify({
    records: OPERATIONAL_DASHBOARD_RECORDS,
    selectedId,
    nodes: OPERATIONAL_DASHBOARD_NODES,
    relationships: OPERATIONAL_DASHBOARD_EDGES,
  });

  return {
    dashboardProfile,
    dashboardRadius,
    dashboardCells,
    dashboardBounds,
    selectedId,
    selectedRecord,
    dashboardJson,
    nodes: OPERATIONAL_DASHBOARD_NODES,
    edges: OPERATIONAL_DASHBOARD_EDGES,
    selectorGroups: OPERATIONAL_DASHBOARD_SELECTOR_GROUPS,
    records: OPERATIONAL_DASHBOARD_RECORDS,
  };
}
